<?php
/**
 * Payments Fee WHMCS - Translations (English / Spanish).
 *
 * The language follows the context: the admin's language in the admin area,
 * the client's language in the client area, and the invoice owner's language
 * (or the system default) when invoices are generated by cron/API.
 */

namespace PaymentsFee;

use WHMCS\Database\Capsule;

class Lang
{
    const ENGLISH = 'english';
    const SPANISH = 'spanish';

    private static $locale = null;
    private static $strings = array();

    public static function t($key, array $replace = array())
    {
        $locale = self::locale();
        $strings = self::load($locale);
        if (isset($strings[$key])) {
            $text = $strings[$key];
        } else {
            $fallback = self::load(self::ENGLISH);
            $text = isset($fallback[$key]) ? $fallback[$key] : $key;
        }
        if ($replace) {
            $pairs = array();
            foreach ($replace as $k => $v) {
                $pairs['{' . $k . '}'] = (string) $v;
            }
            $text = strtr($text, $pairs);
        }
        return $text;
    }

    public static function locale()
    {
        if (self::$locale === null) {
            self::$locale = self::detect();
        }
        return self::$locale;
    }

    public static function setLocale($locale)
    {
        self::$locale = self::normalize($locale);
    }

    /** Decimal separator for percentages shown to people. */
    public static function decimalSeparator()
    {
        return self::locale() === self::SPANISH ? ',' : '.';
    }

    /** Use the language of a client (for invoice lines created without a session). */
    public static function useClientLanguage($userId)
    {
        $lang = '';
        try {
            $lang = (string) Capsule::table('tblclients')->where('id', $userId)->value('language');
        } catch (\Throwable $e) {
            $lang = '';
        }
        self::$locale = $lang !== '' ? self::normalize($lang) : self::normalize(self::systemLanguage());
    }

    public static function normalize($name)
    {
        $n = strtolower(trim((string) $name));
        if ($n === '' ) {
            return self::ENGLISH;
        }
        if (strpos($n, 'spanish') === 0 || strpos($n, 'espa') === 0 || $n === 'es' || strpos($n, 'es_') === 0 || strpos($n, 'es-') === 0) {
            return self::SPANISH;
        }
        return self::ENGLISH;
    }

    private static function detect()
    {
        // Admin area
        if (defined('ADMINAREA') || !empty($_SESSION['adminid'])) {
            $lang = self::adminLanguage();
            if ($lang !== '') {
                return self::normalize($lang);
            }
        }

        // Client area
        try {
            if (class_exists('\\Lang') && method_exists('\\Lang', 'getName')) {
                $name = (string) \Lang::getName();
                if ($name !== '') {
                    return self::normalize($name);
                }
            }
        } catch (\Throwable $e) {
            // ignore
        }
        if (!empty($_SESSION['Language'])) {
            return self::normalize($_SESSION['Language']);
        }

        return self::normalize(self::systemLanguage());
    }

    private static function adminLanguage()
    {
        try {
            if (class_exists('\\AdminLang') && method_exists('\\AdminLang', 'getName')) {
                $name = (string) \AdminLang::getName();
                if ($name !== '') {
                    return $name;
                }
            }
        } catch (\Throwable $e) {
            // ignore
        }
        if (!empty($_SESSION['adminid'])) {
            try {
                return (string) Capsule::table('tbladmins')->where('id', (int) $_SESSION['adminid'])->value('language');
            } catch (\Throwable $e) {
                return '';
            }
        }
        return '';
    }

    private static function systemLanguage()
    {
        try {
            return (string) Capsule::table('tblconfiguration')->where('setting', 'Language')->value('value');
        } catch (\Throwable $e) {
            return '';
        }
    }

    private static function load($locale)
    {
        if (!isset(self::$strings[$locale])) {
            $file = dirname(__DIR__) . '/lang/' . $locale . '.php';
            $_ADDONLANG = array();
            if (is_file($file)) {
                include $file;
            }
            self::$strings[$locale] = $_ADDONLANG;
        }
        return self::$strings[$locale];
    }
}
